{"issue": true, "summary": "When a mapper function fails during iteration, the queue clearing logic doesn't properly reject queued items, leading to orphaned rejections that are not handled by the caller.", "edits": [{"path": "index.js", "old": "while (queue.size > 0) {
					const item = queue.dequeue();
					if (typeof item.reject === 'function') {
						item.reject(abortError);
					}
				}", "new": "while (queue.size > 0) {
					const item = queue.dequeue();
					if (typeof item.reject === 'function') {
						item.reject(abortError);
					} else if (typeof item.run === 'function') {
						// Handle the case where an item is queued but not yet executed
						item.run(); // This ensures the promise chain continues
					}
				}"}]}
